class ThreatAwareSystem {
  constructor(readonly systemId: string, readonly threats: readonly Threat[]) {}

  filtered<S extends Threat>(keep: (t: Threat) => t is S): ThreatAwareSystem {
    return new ThreatAwareSystem(this.systemId, this.threats.filter(keep));
  }
}

